/** Merged view — verbatim wins on collision. */
export const SKILL_META: Record<string, SkillMeta> = {
  ...SKILL_META_GENERATED,
  ...SKILL_META_VERBATIM,
};

/** node-zero's on-map slug resolves to the knowledge-base skill file. */
const SLUG_ALIAS: Record<string, string> = { "node-zero": "knowledge-base" };

/** Resolve at-a-glance metadata for a skill slug (alias-aware). */
export function getSkillMeta(slug: string): SkillMeta | undefined {
  return SKILL_META[SLUG_ALIAS[slug] ?? slug] ?? SKILL_META[slug];
}

/* ---- COVERS ON THE MAP — the jobs that ship a given runnable skill file.
   Computed from the ground truth (PLAYBOOK file membership) + node zero, not a
   stale embedded index. Returns EN job names; callers localize with jobName(). */
let _coversIndex: Record<string, string[]> | null = null;
function buildCoversIndex(): Record<string, string[]> {
  const idx: Record<string, string[]> = {};
  const add = (slug: string, job: string) => {
    const list = (idx[slug] ??= []);
    if (!list.includes(job)) list.push(job);
  };
  for (const [jobName, entry] of Object.entries(PLAYBOOK)) {
    for (const f of entry.files) {
      const slug = f.path.replace(/^skills\//, "").replace(/\.md$/, "");
      add(slug, jobName);
    }
  }
  // node zero ships the knowledge-base + audit files under one card.
  add("knowledge-base", NODE_ZERO.cardTitle);
  add("skilltree-audit", NODE_ZERO.cardTitle);
  return idx;
}
/** EN job names that cover this skill slug on the map (alias-aware). */
export function skillCovers(slug: string): string[] {
  _coversIndex ??= buildCoversIndex();
  const s = SLUG_ALIAS[slug] ?? slug;
  return _coversIndex[s] ?? _coversIndex[slug] ?? [];
}
